<?php
/**
 * Proof — what the read tools answer (docs/knowledge-mcp-tool-surface.md): bases, sources and sections, guidelines and areas, builds. Each answer is compared with the database's own word (SQL asked as the same member) or with
 * the world the proofs built: counts, filters, paging, the outline's Markdown, the neighbours, the excerpt's matching rules (case and whitespace), the pages, the curator's half of get_base, the resolvers' plain list.
 */
require __DIR__ . '/lib.php';
$w = p4_world();
$a = $w['ask'];
$hb = $a['handbook'];
$k = $w['keys'];

// a rerun against the same stack starts from the world as it was
pdo()->exec("DELETE FROM sources WHERE base_id = $hb AND title IN ('p4 page', 'p4 forgotten')");
pdo()->exec("DELETE FROM source_focus_areas WHERE source_id = {$a['source']}");
pdo()->exec("DELETE FROM focus_areas WHERE base_id = $hb AND slug = 'p4-proposed'");

echo "1. Bases\n";
$t = tool(PRIYA, 'find_bases', ['q' => 'smoke-handbook']);
ok(!$t['error'] && count($t['data']) === 1 && array_keys($t['data'][0]) === ['base_id', 'name', 'key'], 'q alone resolves a base by its key: a plain list of {base_id, name, key}');
$t = tool(PRIYA, 'find_bases', ['q' => 'handb']);
ok(count($t['data']) === 1 && $t['data'][0]['base_id'] === $hb, '...or by words of its name');
$t = tool(PRIYA, 'find_bases', ['status' => 'ready', 'limit' => 100]);
ok(!$t['error'] && count($t['data']) >= 1 && count(array_filter($t['data'], fn ($r) => $r['status'] !== 'ready')) === 0, 'status filters');
$t = tool(PRIYA, 'find_bases', ['limit' => 100]);
$row = find_row($t['data'], 'base_id', $hb);
ok($row !== null && $row['source_count'] === 1 && $row['section_count'] === 4 && $row['area_count'] === 1 && $row['pinned_count'] === 1 && $row['my_level'] === 'read' && $row['i_curate'] === false && $row['owner_name'] === 'SMOKE Marco', 'a row carries the counts and Priya\'s level (read, not a curator)');
ok(strlen($row['description']) <= 300, 'description cut to 300');
$all = count(tdata(OWNER, 'find_bases', ['limit' => 100]));
$p1 = tdata(OWNER, 'find_bases', ['limit' => 2, 'offset' => 0]);
$p2 = tdata(OWNER, 'find_bases', ['limit' => 2, 'offset' => 2]);
ok(count($p1) === 2 && count($p2) >= 1 && ids($p1, 'base_id') !== ids($p2, 'base_id') && count(array_intersect(ids($p1, 'base_id'), ids($p2, 'base_id'))) === 0, 'limit and offset page');
$wallId = base_by_key('p4-wall') ?? make_base(MARCO, 'SMOKE Wall', ['key' => 'p4-wall']);
pdo()->exec("UPDATE knowledge_bases SET archived_at = now() WHERE id = $wallId");
ok(!in_array($wallId, ids(tdata(MARCO, 'find_bases', ['limit' => 100]), 'base_id'), true) && in_array($wallId, ids(tdata(MARCO, 'find_bases', ['limit' => 100, 'include_archived' => true]), 'base_id'), true), 'an archived base is left out unless asked for');
pdo()->exec("UPDATE knowledge_bases SET archived_at = NULL WHERE id = $wallId");
$t = tool(MARCO, 'get_base', ['base' => $hb]);
$d = $t['data'];
ok(!$t['error'] && $d['key'] === 'smoke-handbook' && $d['my_level'] === 'own' && $d['sources']['total'] === 1 && $d['sections']['total'] === 4 && isset($d['guidelines'], $d['estimate'], $d['keys_count'], $d['open_proposals'], $d['gaps_30d']), 'get_base for the owner: counts, areas, and the curator half (guidelines, estimate, keys, proposals, gaps)');
$d = tdata(PRIYA, 'get_base', ['base' => 'SMOKE Handbook']);
ok($d['base_id'] === $hb && $d['my_level'] === 'read' && !isset($d['guidelines']) && !isset($d['estimate']) && !isset($d['keys_count']) && count($d['areas']) === 1 && count($d['curators']) >= 1, 'get_base for a reader (by name): no curator half; the areas and the curators');
$t = tool(MARCO, 'base_members', ['base' => $hb]);
ok(!$t['error'] && $t['data'][0]['principal_kind'] === 'owner' && $t['data'][0]['principal_name'] === 'SMOKE Marco' && count($t['data']) >= 3, 'base_members: the owner first, then the shares');
$t = tool(MARCO, 'base_members', ['base' => $hb, 'kind' => 'everyone']);
ok(count($t['data']) === 1 && $t['data'][0]['principal_kind'] === 'everyone' && $t['data'][0]['principal_name'] === 'Everyone in the business', 'and by kind');
$t = tool(MARCO, 'base_members', ['base' => $k['manuals'], 'kind' => 'application']);
ok($t['data'][0]['principal_ref'] === 'helpdesk' && $t['data'][0]['principal_name'] === 'helpdesk', 'an application principal is named by its catalog key');
$st = tdata(PRIYA, 'get_settings');
ok($st['max_question_chars'] === 2000 && $st['conversation_turns'] === 3 && $st['evidence_threshold'] === 0.6 && isset($st['section_target_chars']) && !array_key_exists('updated_by', $st), 'get_settings: limits and thresholds');
$tp = tdata(PRIYA, 'find_templates');
ok(count($tp) >= 1 && isset($tp[0]['guidelines'], $tp[0]['subject_types'], $tp[0]['default_visibility']), 'find_templates: the shipped sets');
$one = tdata(PRIYA, 'find_templates', ['q' => 'general']);
ok(count($one) === 1 && array_keys($one[0]) === ['template_key', 'name'], 'q alone resolves a template: {template_key, name}');

echo "2. Sources and sections\n";
$src = $a['source'];
$rows = tdata(PRIYA, 'find_sources', ['base' => $hb]);
ok(count($rows) === 1 && $rows[0]['title'] === 'Staff handbook' && $rows[0]['sections_count'] === 4 && $rows[0]['status'] === 'ready' && $rows[0]['origin'] === null && $rows[0]['is_stale'] === false, 'find_sources: the handbook, ready, four sections; origin only for an address');
ok(tdata(PRIYA, 'find_sources', ['base' => $hb, 'kind' => 'url']) === [] && count(tdata(PRIYA, 'find_sources', ['base' => $hb, 'kind' => 'text'])) === 1, 'kind filters');
ok(tdata(PRIYA, 'find_sources', ['base' => $hb, 'status' => 'failed']) === [] && count(tdata(PRIYA, 'find_sources', ['base' => $hb, 'stale' => false])) === 1 && tdata(PRIYA, 'find_sources', ['base' => $hb, 'stale' => true]) === [], 'status and stale filter');
ok(tdata(PRIYA, 'find_sources', ['base' => $hb, 'area' => 'leave']) === [], 'area filter (no source is in the Leave area yet)');
pdo()->exec("INSERT INTO source_focus_areas (source_id, focus_area_id) VALUES ($src, {$a['leave']}) ON CONFLICT DO NOTHING");
ok(count(tdata(PRIYA, 'find_sources', ['base' => $hb, 'area' => 'leave'])) === 1 && tdata(PRIYA, 'find_sources', ['base' => $hb, 'area' => $a['leave']])[0]['focus_area_ids'] === [$a['leave']], '...and after the assignment it lists the source (the area by slug or id)');
$u = tool(MARCO, 'find_sources', ['base' => $hb, 'q' => 'handbook']);
ok(!$u['error'] && count($u['data']) === 1, 'q with a base narrows by title');
$u = tool(PRIYA, 'find_sources', []);
ok($u['code'] === 'invalid_argument' && $u['data']['error']['fields'] === ['base'], 'no base and no q: invalid_argument naming base');
$url = (int) one("INSERT INTO sources (base_id, kind, title, origin, added_by, status, error) VALUES (:b, 'url', 'p4 page', 'https://docs.example.test/a/b', :m, 'failed', :e) RETURNING id", ['b' => $hb, 'm' => MARCO, 'e' => str_repeat('p4 long error ', 40)]);
$fo = (int) one("INSERT INTO sources (base_id, kind, title, origin, added_by, status) VALUES (:b, 'text', 'p4 forgotten', 'paste', :m, 'ready') RETURNING id", ['b' => $hb, 'm' => MARCO]);
pdo()->exec("UPDATE sources SET status = 'forgotten', forgotten_at = now() WHERE id = $fo");
$rows = tdata(PRIYA, 'find_sources', ['base' => $hb]);
$ur = find_row($rows, 'source_id', $url);
ok($ur['origin'] === 'https://docs.example.test/a/b' && strlen($ur['error']) <= 300 && find_row($rows, 'source_id', $fo) === null, 'an address source shows its URL, its error cut to 300; a forgotten source is not listed');
ok(find_row(tdata(PRIYA, 'find_sources', ['base' => $hb, 'include_forgotten' => true]), 'source_id', $fo) === null, 'a reader cannot ask for the forgotten ones');
ok(find_row(tdata(MARCO, 'find_sources', ['base' => $hb, 'include_forgotten' => true]), 'source_id', $fo) !== null, 'the curator can');
$gs = tdata(PRIYA, 'get_source', ['source' => 'Staff handbook']);
ok($gs['source']['source_id'] === $src && $gs['pages']['count'] === 2 && $gs['pages']['first'] === 3 && $gs['pages']['last'] === 4 && count($gs['areas']) === 1 && $gs['areas'][0]['slug'] === 'leave' && $gs['file'] === null, 'get_source: pages, areas, no file (a text source)');
ok(count($gs['outline']) === 2 && $gs['outline'][0]['heading'] === 'Leave' && $gs['outline'][1]['heading'] === 'Pay', 'its outline: the top-level headings only');
$gu = tdata(PRIYA, 'get_source', ['source' => $url]);
ok($gu['source']['origin'] === 'https://docs.example.test/a/b' && mb_strlen($gu['source']['error']) <= 300, 'an address source: origin');
$ol = tdata(PRIYA, 'source_outline', ['source' => $src]);
ok($ol['markdown'] === "- Leave [#{$a['carry']}-1]" || str_contains($ol['markdown'], "- Carry-over (p. 3) [#{$a['carry']}]"), 'source_outline: one line per section - Heading (p. 3) [#id]');
ok(str_contains($ol['markdown'], "\n  - Carry-over (p. 3) [#{$a['carry']}]") && count($ol['sections']) === 4 && $ol['truncated'] === false, '...indented by level; four sections');
$o1 = tdata(PRIYA, 'source_outline', ['source' => $src, 'depth' => 1]);
ok(count($o1['sections']) === 2 && !str_contains($o1['markdown'], 'Carry-over'), 'depth 1: the top level only');
$sec = tdata(PRIYA, 'get_section', ['section' => $a['carry']]);
ok($sec['source']['title'] === 'Staff handbook' && $sec['page_no'] === 3 && str_contains($sec['markdown'], 'Up to five days of unused leave') && str_starts_with($sec['markdown'], '# Staff handbook › Leave › Carry-over') && $sec['status'] === 'extracted', 'get_section: the heading path, the words in Markdown, source and page');
ok($sec['prev_section_id'] !== null && $sec['next_section_id'] === $a['sick'], '...and its neighbours');
$bare = tdata(PRIYA, 'get_section', ['section' => $a['carry'], 'with_neighbours' => false]);
ok(!array_key_exists('prev_section_id', $bare), 'with_neighbours: false leaves them out');
$sp = tdata(PRIYA, 'source_page', ['source' => $src, 'page' => 3]);
ok($sp['page'] === 3 && $sp['page_count'] === 2 && count($sp['sections']) >= 1 && str_contains($sp['sections'][0]['markdown'], 'five days') && $sp['truncated'] === false, 'source_page: the sections on page 3');
ok(tool(PRIYA, 'source_page', ['source' => $src, 'page' => 9])['code'] === 'not_found', '...a page the source does not have: not_found');
$x = tdata(PRIYA, 'source_excerpt', ['section' => $a['carry'], 'quote' => 'FIVE   days of unused']);
ok($x['found'] === true && $x['match'] === 'five days of unused' && $x['before'] === 'Up to ' && strlen($x['after']) <= 600, 'source_excerpt: case and whitespace runs are ignored; the match is the section\'s own words');
$x = tdata(PRIYA, 'source_excerpt', ['section' => $a['carry'], 'quote' => 'ten paid sick days', 'window' => 100]);
ok($x['found'] === false && $x['before'] === '' && $x['match'] === '' && strlen($x['after']) <= 200 && strlen($x['after']) > 0, 'a quote that is not in the section: found false and the section\'s opening (2 x window)');
$x = tdata(PRIYA, 'source_excerpt', ['question' => $w['q_carry'], 'n' => 2]);
ok($x['found'] === true && $x['section_id'] === $a['sick'] && $x['match'] === 'ten paid sick days a year', 'by question and citation number: the citation\'s own quote, in its own section');
$x = tdata(PRIYA, 'source_excerpt', ['section' => $a['carry'], 'quote' => 'five', 'window' => 100]);
ok(strlen($x['before']) <= 100 && strlen($x['after']) <= 100, 'the window bounds each side');
ok(tool(PRIYA, 'source_excerpt', ['question' => $w['q_carry'], 'n' => 9])['code'] === 'not_found' && tool(PRIYA, 'source_excerpt', [])['code'] === 'invalid_argument', 'a citation that is not there: not_found; nothing named: invalid_argument');
$edge = tdata(PRIYA, 'source_excerpt', ['section' => $a['carry'], 'quote' => 'Up to five', 'window' => 1500]);
$secText = (string) one('SELECT text FROM sections WHERE id = :s', ['s' => $a['carry']]);
ok($edge['before'] === '' && str_starts_with($secText, $edge['match']) && strlen($edge['before'] . $edge['match'] . $edge['after']) <= strlen($secText), 'an excerpt never crosses the section\'s edge');
$fd = tdata(MARCO, 'find_feeds', ['base' => $hb]);
ok(count($fd) === 1 && $fd[0]['provider'] === 'spaces' && $fd[0]['tool'] === 'pages_index' && $fd[0]['last_status'] === 'no_connection', 'find_feeds: the Spaces feed and its last status');
$fq = tdata(MARCO, 'find_feeds', ['q' => 'spaces.pages']);
ok(count($fq) === 1 && array_keys($fq[0]) === ['feed_id', 'tool', 'base_id'] && $fq[0]['tool'] === 'spaces.pages_index', 'q alone resolves a feed by provider.tool');

echo "3. Guidelines and focus areas\n";
$gl = tdata(MARCO, 'find_guidelines', ['base' => $hb]);
ok($gl['base_guideline_version'] >= 1 && count($gl['guidelines']) >= 3 && find_row($gl['guidelines'], 'title', 'SMOKE Answer briefly')['shapes_graph'] === false, 'find_guidelines: the base\'s version and its guidelines; answering does not shape the graph');
$ex = tdata(MARCO, 'find_guidelines', ['base' => $hb, 'kind' => 'extraction']);
ok(count($ex['guidelines']) >= 1 && count(array_filter($ex['guidelines'], fn ($r) => $r['kind'] !== 'extraction' || $r['shapes_graph'] !== true)) === 0, 'by kind: extraction shapes the graph');
$gq = tdata(MARCO, 'find_guidelines', ['q' => 'briefly']);
ok(count($gq) === 1 && array_keys($gq[0]) === ['guideline_id', 'title', 'kind', 'base_id'], 'q alone resolves a guideline by its title');
$gv = tdata(MARCO, 'guideline_versions', ['base' => $hb]);
ok($gv['base_guideline_version'] === $gl['base_guideline_version'] && count($gv['versions']) >= 3 && is_array($gv['built_under']) && $gv['stale_sections'] === 0 && $gv['versions'][0]['saved_at'] >= $gv['versions'][1]['saved_at'], 'guideline_versions: the history newest first, what the graph is built under, no stale section');
$one = (int) find_row($gl['guidelines'], 'title', 'SMOKE Answer briefly')['guideline_id'];
$gv1 = tdata(MARCO, 'guideline_versions', ['base' => $hb, 'guideline' => $one]);
ok(count($gv1['versions']) >= 1 && count(array_filter($gv1['versions'], fn ($r) => $r['guideline_id'] !== $one)) === 0, '...one guideline\'s history');
$vo = tdata(MARCO, 'find_vocabulary', ['base' => $hb]);
ok(count($vo) === 1 && $vo[0]['canonical_name'] === 'PTO' && $vo[0]['aliases'] === ['paid time off'] && $vo[0]['seeded'] === false, 'find_vocabulary: PTO with its alias');
$vq = tdata(MARCO, 'find_vocabulary', ['q' => 'paid time']);
ok(count($vq) === 1 && array_keys($vq[0]) === ['term_id', 'canonical_name', 'base_id'], 'q alone finds a term by its alias');
$ut = tdata(MARCO, 'unused_terms', ['base' => $hb]);
ok(count($ut) === 1 && $ut[0]['canonical_name'] === 'PTO', 'unused_terms: PTO is in no section');
$fa = tdata(PRIYA, 'find_focus_areas', ['base' => $hb]);
ok(count($fa) === 1 && $fa[0]['slug'] === 'leave' && $fa[0]['source_count'] === 1 && count($fa[0]['example_questions']) === 2 && !array_key_exists('maludb_project_id', $fa[0]), 'find_focus_areas: the area with its example questions, size, no engine id');
$fz = tdata(PRIYA, 'find_focus_areas', ['q' => 'lea']);
ok(count($fz) === 1 && array_keys($fz[0]) === ['focus_area_id', 'name', 'base_name'], 'q alone resolves an area across my bases');
$prop = (int) one("INSERT INTO focus_areas (base_id, name, slug, status, proposed_by, proposal_note) VALUES (:b, 'p4 Proposed', 'p4-proposed', 'proposed', :m, 'p4 note') RETURNING id", ['b' => $hb, 'm' => SEAMUS]);
$fa = tdata(PRIYA, 'find_focus_areas', ['base' => $hb]);
ok(count($fa) === 2 && find_row($fa, 'slug', 'p4-proposed')['proposed_by_name'] === 'SMOKE Seamus', 'a proposed area shows who proposed it');
ok(count(tdata(PRIYA, 'find_focus_areas', ['base' => $hb, 'status' => 'active'])) === 1, '...and status filters');
$fo = tdata(PRIYA, 'get_focus_area', ['area' => 'leave', 'base' => 'smoke-handbook']);
ok($fo['area']['slug'] === 'leave' && count($fo['sources']) === 1 && $fo['section_count'] === 4, 'get_focus_area: the area, its sources and their sections');
$un = tdata(MARCO, 'unassigned_sources', ['base' => $hb]);
ok(count(array_filter($un, fn ($r) => $r['source_id'] === $src)) === 0 && find_row($un, 'source_id', $url) !== null, 'unassigned_sources: the address source, not the handbook (it is in Leave)');
$ea = tdata(MARCO, 'empty_areas', ['base' => $hb]);
ok(find_row($ea, 'slug', 'p4-proposed') !== null && find_row($ea, 'slug', 'leave') === null, 'empty_areas: the proposed area, not Leave');
pdo()->exec("DELETE FROM focus_areas WHERE id = $prop");
pdo()->exec("DELETE FROM sources WHERE base_id = $hb AND title IN ('p4 page', 'p4 forgotten')");
pdo()->exec("DELETE FROM source_focus_areas WHERE source_id = $src");

echo "4. Builds\n";
$bp = tdata(MARCO, 'build_progress', ['base' => $hb]);
ok($bp['build_id'] === $w['build'] && $bp['status'] === 'failed' && $bp['items_failed'] >= 0 && $bp['failed_items_truncated'] === false && count($bp['failed_items']) === 1 && $bp['failed_items'][0]['error'] === 'p4 engine said no', 'build_progress by base: the last build, its failed item and the engine\'s words');
$bi = tdata(MARCO, 'build_progress', ['build' => $w['build'], 'items' => 'failed']);
ok(count($bi['items']) === 1 && $bi['items'][0]['status'] === 'failed' && $bi['items'][0]['heading_path'] === 'Staff handbook › Leave › Carry-over', 'with items: the failed item with its heading path');
ok(tool(PRIYA, 'build_progress', ['build' => $w['build']])['code'] === 'not_found', 'a build of a base one does not curate: not_found (the view shows nothing)');
ok(tool(MARCO, 'build_progress', ['base' => $a['empty']])['code'] === 'not_found', 'a base never built: not_found');
$fb = tdata(MARCO, 'find_builds', ['base' => $hb]);
ok(count($fb) === 1 && $fb[0]['status'] === 'failed' && $fb[0]['started_by_name'] === 'SMOKE Marco' && !array_key_exists('usage', $fb[0]), 'find_builds: the build; no usage without the costs right');
$fb = tdata(OWNER, 'find_builds', []);
ok(count($fb) >= 1 && array_key_exists('usage', $fb[0]), 'the admin lists every base\'s builds, with usage');
ok(tdata(MARCO, 'find_builds', ['base' => $hb, 'status' => 'done']) === [] && tool(MARCO, 'find_builds', ['base' => $hb, 'status' => 'bogus'])['error'], 'status filters; a status that is not one is refused');
$be = tdata(MARCO, 'build_estimate', ['base' => $hb]);
ok($be['kind'] === 'extract' && isset($be['within_limit'], $be['month_limit_chars'], $be['remaining_chars']) && $be['total_sections'] === 4, 'build_estimate: sections, characters, the month against its limit');
$ba = tdata(MARCO, 'build_estimate', ['base' => $hb, 'kind' => 'rebuild_all']);
ok($ba['sections'] === 4 && $ba['characters'] >= $be['characters'], 'rebuild_all counts every live section');
$bu = tdata(MARCO, 'base_usage', ['base' => $hb]);
ok(count($bu['rows']) >= 1 && $bu['rows'][0]['kind'] === 'answer' && $bu['month_limit_chars'] === 52428800 && !str_contains(json_encode($bu), 'dollar') && !str_contains(json_encode($bu), 'cost'), 'base_usage: the month\'s engine use by kind, against its limit — tokens and characters, never dollars');
ok(tool(MARCO, 'base_usage', ['base' => $hb, 'month' => '2026-13'])['code'] === 'invalid_argument', 'a month that is not YYYY-MM: invalid_argument');
ok(tdata(MARCO, 'base_usage', ['base' => $hb, 'month' => '2020-01'])['rows'] === [], 'a month with no use: no rows');
$all = tool(OWNER, 'base_usage', []);
ok(!$all['error'] && count($all['data']) >= 1 && isset($all['data'][0]['base_name']), 'with no base the admin reads every base\'s use');
ok(tool(MARCO, 'base_usage', [])['code'] === 'curators_only', '...and a curator without the costs right does not');

echo "5. Notes and notices\n";
$fn = tdata(PRIYA, 'find_notes', ['record_type' => 'base', 'record_id' => $hb]);
ok(count($fn) === 1 && $fn[0]['body'] === 'p4 note on the handbook' && $fn[0]['member_name'] === 'SMOKE Marco', 'find_notes: the note on the base, who wrote it');
ok(tdata(BEA, 'find_notes', ['record_type' => 'base', 'record_id' => $a['private']]) === [] && tool(PRIYA, 'find_notes', ['record_type' => 'bogus', 'record_id' => 1])['code'] === 'invalid_argument', 'a private base\'s notes are not Bea\'s; a record type that is not one is refused');
pdo()->exec("DELETE FROM notifications WHERE title LIKE 'p4 %'");
pdo()->exec("INSERT INTO notifications (member_id, kind, record_type, record_id, title, body, read_at) VALUES (" . PRIYA . ", 'shared', 'base', $hb, 'p4 read notice', NULL, now() - interval '1 day'), (" . PRIYA . ", 'build_done', 'base', $hb, 'p4 unread notice', 'p4 body', NULL), (" . BEA . ", 'shared', 'base', $hb, 'p4 not hers', NULL, NULL)");
$mn = tdata(PRIYA, 'my_notifications');
ok(isset($mn['prefs']) || $mn['prefs'] === null, 'my_notifications: the preferences (null until she sets them)');
$mine = array_values(array_filter($mn['notifications'], fn ($n) => str_starts_with($n['title'], 'p4 ')));
ok(count($mine) === 2 && $mine[0]['title'] === 'p4 unread notice' && $mine[0]['read_at'] === null && $mine[1]['title'] === 'p4 read notice', 'my notices, unread first, hers alone (not Bea\'s)');
$mu = array_values(array_filter(tdata(PRIYA, 'my_notifications', ['unread_only' => true])['notifications'], fn ($n) => str_starts_with($n['title'], 'p4 ')));
ok(count($mu) === 1 && $mu[0]['kind'] === 'build_done', 'unread_only');
pdo()->exec("DELETE FROM notifications WHERE title LIKE 'p4 %'");
finish();
